package com.smartapproval.web;
import com.smartapproval.exception.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { record ErrorBody(Instant timestamp,int status,String message,Map<String,String> errors){}
 @ExceptionHandler(NotFoundException.class) ResponseEntity<ErrorBody> notFound(RuntimeException e){return body(HttpStatus.NOT_FOUND,e.getMessage(),Map.of());} @ExceptionHandler(InvalidDecisionException.class) ResponseEntity<ErrorBody> conflict(RuntimeException e){return body(HttpStatus.CONFLICT,e.getMessage(),Map.of());}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorBody> validation(MethodArgumentNotValidException e){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return body(HttpStatus.BAD_REQUEST,"Datos inválidos",errors);} @ExceptionHandler({org.springframework.web.method.annotation.MethodArgumentTypeMismatchException.class,org.springframework.http.converter.HttpMessageNotReadableException.class}) ResponseEntity<ErrorBody> malformed(Exception e){return body(HttpStatus.BAD_REQUEST,"Formato de solicitud inválido",Map.of());} private ResponseEntity<ErrorBody> body(HttpStatus s,String m,Map<String,String> e){return ResponseEntity.status(s).body(new ErrorBody(Instant.now(),s.value(),m,e));}
}
